usage:
const form = useForm({
  defaultValues: { email: '', password: '' },
  onSubmit: async (values) => {
    await signIn(values);
  },
});

<Form form={form}>
  <Form.Field
    name="email"
    validate={(value) => (value.includes('@') ? undefined : 'Enter a valid email')}
  >
    {(field) => (
      <Input
        label="Email"
        value={field.value}
        onChangeText={field.onChange}
        onBlur={field.onBlur}
        errorMessage={field.error}
      />
    )}
  </Form.Field>

  <Form.Field
    name="password"
    validate={(value) => (value.length >= 8 ? undefined : 'At least 8 characters')}
  >
    {(field) => (
      <Input
        label="Password"
        secureTextEntry
        value={field.value}
        onChangeText={field.onChange}
        onBlur={field.onBlur}
        errorMessage={field.error}
      />
    )}
  </Form.Field>

  <Button loading={form.isSubmitting} onPress={form.handleSubmit}>
    Sign in
  </Button>
</Form>

