const form = useForm({
  defaultValues: { name: '', email: '', password: '', confirmPassword: '', acceptedTerms: false },
  validate: (values) =>
    values.password !== values.confirmPassword
      ? { confirmPassword: 'Passwords must match' }
      : {},
  onSubmit: async (values) => {
    await createAccount(values);
  },
});

<Form form={form}>
  <Form.Field name="acceptedTerms" validate={(value) => (value ? undefined : 'Required to continue')}>
    {(field) => (
      <Field invalid={!!field.error}>
        <Checkbox checked={field.value} onCheckedChange={field.onChange} label="I accept the terms" />
        <Field.Error>{field.error}</Field.Error>
      </Field>
    )}
  </Form.Field>
  <Button loading={form.isSubmitting} onPress={form.handleSubmit}>Create account</Button>
</Form>
